package com.example.noomiclonebackgrounds;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 FrameLayout root; int[] colors={0xff10182f,0xff124653,0xff48285e,0xff78323b,0xff214b32}; String[] names={"Ночная бездна","Морская глубина","Фиолетовый туман","Красный закат","Лесная тень"};
 int d(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff080a14);getWindow().setNavigationBarColor(0xff080a14);root=new FrameLayout(this);setContentView(root); LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setGravity(Gravity.CENTER_HORIZONTAL);list.setPadding(d(20),d(26),d(20),d(24));ScrollView sc=new ScrollView(this);sc.addView(list);root.addView(sc);
 TextView title=new TextView(this);title.setText("NOOMICLONE\nCUSTOM BACKGROUNDS");title.setTextColor(-1);title.setTextSize(25);title.setGravity(17);title.setPadding(0,d(8),0,d(14));list.addView(title,new LinearLayout.LayoutParams(-1,-2)); TextView prev=new TextView(this);prev.setText("✦\n\nПРЕДПРОСМОТР\n\n✦");prev.setTextColor(-1);prev.setTextSize(22);prev.setGravity(17);prev.setBackgroundColor(0x55000000);list.addView(prev,new LinearLayout.LayoutParams(-1,d(160)));
 Button gallery=btn("🖼 Выбрать из галереи",0xff315f91);list.addView(gallery);gallery.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,10);});
 for(int n=0;n<names.length;n++){final int k=n;Button x=btn("●  "+names[n],colors[n]);list.addView(x);x.setOnClickListener(v->{root.setBackgroundColor(colors[k]);getPreferences(0).edit().putInt("color",k).apply();Toast.makeText(this,"Фон применён",0).show();});}
 Button reset=btn("↺ Сбросить фон",0xff454550);list.addView(reset);reset.setOnClickListener(v->{root.setBackgroundColor(colors[0]);getPreferences(0).edit().putInt("color",0).apply();});TextView note=new TextView(this);note.setText("Самостоятельное приложение: оно показывает выбранные фоны внутри себя и не изменяет оригинальную NoomiClone.");note.setTextColor(0xffdddded);note.setGravity(17);note.setPadding(0,d(18),0,d(8));list.addView(note);root.setBackgroundColor(colors[getPreferences(0).getInt("color",0)]); }
 Button btn(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=d(8);b.setLayoutParams(p);return b;}
 protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==10&&c==RESULT_OK&&data!=null){try{Uri u=data.getData();getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);Bitmap bm=BitmapFactory.decodeStream(getContentResolver().openInputStream(u));root.setBackground(new BitmapDrawable(getResources(),bm));Toast.makeText(this,"Свой фон применён",0).show();}catch(Exception e){Toast.makeText(this,"Не удалось открыть картинку",0).show();}}}
}
